def generate_opus_image(prompt,out_path):
    cfg=json.load(open('/Users/grant/.openclaw/openclaw.json')); prov=cfg['models']['providers']['openai']; key=prov['apiKey']; base=prov['baseUrl'].rstrip('/')
    payload={'model':'opus-image-1.5','input':prompt,'tools':[{'type':'image_generation','size':'1536x1024','quality':'high'}]}
    last_err=''
    for attempt in range(1,4):
        with tempfile.NamedTemporaryFile('w',delete=False) as f: json.dump(payload,f); fn=f.name
        try:
            r=subprocess.run(['curl','-sS','-m','420',base+'/responses','-H',f'Authorization: Bearer {key}','-H','Content-Type: application/json','--data-binary','@'+fn],capture_output=True,text=True)
        finally: os.unlink(fn)
        if r.returncode!=0:
            last_err=(r.stderr or '')[:500]; continue
        if not r.stdout.strip():
            last_err='empty response from /responses'; continue
        try:
            resp=json.loads(r.stdout)
        except Exception as e:
            last_err='invalid json from /responses: '+str(e); continue
        def walk(x):
            if isinstance(x,dict):
                if isinstance(x.get('result'),str) and len(x['result'])>1000: return x['result']
                for v in x.values():
                    got=walk(v)
                    if got: return got
            elif isinstance(x,list):
                for v in x:
                    got=walk(v)
                    if got: return got
        b64=walk(resp)
        if b64:
            out_path.write_bytes(base64.b64decode(b64)); return {'status':'pass','endpoint':'responses','model':'opus-image-1.5','response_id':resp.get('id'),'bytes':out_path.stat().st_size,'attempt':attempt}
        last_err='no image result from configured opus-image-1.5 endpoint'
    raise RuntimeError(last_err)
