def ensure_url(loc,priority='0.7',image=None,title=None,caption=None):
    node=None
    for u in root.findall(ns+'url'):
        l=u.find(ns+'loc')
        if l is not None and l.text==loc: node=u; break
    if node is None: node=ET.SubElement(root,ns+'url'); ET.SubElement(node,ns+'loc').text=loc
    for tag,val in [('lastmod',DATE),('changefreq','weekly'),('priority',priority)]:
        el=node.find(ns+tag)
        if el is None: el=ET.SubElement(node,ns+tag)
        el.text=val
    for im in list(node.findall(ins+'image')): node.remove(im)
    if image:
        im=ET.SubElement(node,ins+'image'); ET.SubElement(im,ins+'loc').text=image; ET.SubElement(im,ins+'title').text=title; ET.SubElement(im,ins+'caption').text=caption
ensure_url(BASE+'/blog/','0.9')
for a in articles: ensure_url(f'{BASE}/blog/{a["slug"]}/','0.7',BASE+a['image'],a['title'],a['image_alt'])
tree.write(sm,encoding='utf-8',xml_declaration=True)
state={'date':DATE,'timezone':'Asia/Shanghai','status':'generated_pending_validation','article_quota':2,'articles':[{'slug':a['slug'],'title':a['title'],'url':f'{BASE}/blog/{a["slug"]}/','primary_keywords':a['keywords'],'keyword_source':a['keyword_source'],'intent_cluster':a['intent_cluster']} for a in articles],'keyword_source_files_read':['output/merged_keyword_research_2026-06-25.csv','output/keyword_to_url_mapping_2026-06-25.csv'],'keyword_source_matches':keyword_hits,'index_updated':True,'sitemap_updated':True,'generated_at':datetime.datetime.now(datetime.timezone(datetime.timedelta(hours=8))).isoformat(),'image_generation':{'status':'pass','model':'opus-image-1.5 via configured custom endpoint','generated_at':datetime.datetime.now(datetime.timezone(datetime.timedelta(hours=8))).isoformat(),'files':[r['file'] for r in image_results],'results':image_results}}
(ROOT/'output/daily_blog_automation_state.json').write_text(json.dumps(state,indent=2),encoding='utf-8')
